import json
from pathlib import Path

def load(stamp):
 s=Path(fr'backend\tests\InvoiceApp.Tests\StrykerOutput\{stamp}\reports\mutation-report.html').read_text(encoding='utf-8')
 a=s.index('app.report = ')+len('app.report = '); b=s.index(';\n\n            function updateTheme()',a); return json.loads(s[a:b])
base=load('2026-11-12.23-18-54'); final=load('2026-11-12.23-31-51')
tests={t['id']:t['name'].split('.')[-1] for d in final['testFiles'].values() for t in d['tests']}
for path,d in base['files'].items():
 for m in d['mutants']:
  if m['status'] not in ('Survived','NoCoverage'): continue
  orig=d['source'].splitlines()[m['location']['start']['line']-1].strip()
  finaldata=next((v for p,v in final['files'].items() if p.endswith(Path(path).name)),None)
  matches=[]
  if finaldata:
   for fm in finaldata['mutants']:
    if fm['mutatorName']==m['mutatorName'] and fm['replacement']==m['replacement']:
     final_source=finaldata['source'].splitlines()
     fl=fm['location']['start']['line']
     if final_source[fl-1].strip()==orig:
      matches.append(fm)
  result='NO MATCH'
  if len(matches)==1:
   fm=matches[0]
   result=f"{fm['status']}: "+', '.join(tests.get(x,x) for x in fm.get('killedBy',[]))
  elif len(matches)>1: result='MULTI '+str([(x['status'],x['location']['start']['line']) for x in matches])
  print(f"{m['status']}\t{Path(path).name}:{m['location']['start']['line']}\t{m['mutatorName']}\t{result}")
print('FINAL statuses:', {status:sum(1 for d in final['files'].values() for m in d['mutants'] if m['status']==status) for status in ['Killed','Survived','NoCoverage','Ignored']})
'@ | python -","description":"Map baseline mutants to final tests"}

